    def index():
        if request.method == 'POST':
            try:
                customer, event, quantity = [int(request.form[k]) for k in ['customer','event','quantity']]
                if not 1 <= quantity <= 8:
                    raise ValueError()
                with connect() as conn:
                    conn.execute('INSERT INTO Booking VALUES(?,?,?)',(customer,event,quantity))
