def counts(values, target):
    a, bubble = values[:], 0
    for end in range(len(a) - 1, 0, -1):
        changed = False
        for j in range(end):
            bubble += 1
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                changed = True
        if not changed:
            break
    b, insertion = values[:], 0
    for i in range(1, len(b)):
        key, j = b[i], i - 1
        while j >= 0:
            insertion += 1
            if b[j] <= key:
                break
            b[j + 1] = b[j]
            j -= 1
        b[j + 1] = key
    left, right, binary = 0, len(a) - 1, 0
    while left <= right:
        mid = (left + right) // 2
        binary += 1
        if a[mid] == target:
            break
        if a[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return [bubble, insertion, binary]

def shift_ascii(text, step):
    result = ''
    for char in text:
        if 'A' <= char <= 'Z':
            char = chr((ord(char) - ord('A') + step) % 26 + ord('A'))
        elif 'a' <= char <= 'z':
            char = chr((ord(char) - ord('a') + step) % 26 + ord('a'))
        result += char
    return [result, len(result), len(result.encode('utf-8'))]

